EmberViewport.prototype.updateColliderGuide=function(s,show){
 const T=Ember3D;if(!this.colliderGuides){const material=new T.LineBasicMaterial({color:0x54d8ff,transparent:true,opacity:.5,depthWrite:false});const sphere=new T.LineSegments(new T.WireframeGeometry(new T.SphereGeometry(1,16,8)),material);const box=new T.LineSegments(new T.EdgesGeometry(new T.BoxGeometry(1,1,1)),material);const plane=new T.GridHelper(600,12,0x54d8ff,0x54d8ff);plane.rotation.x=Math.PI/2;plane.material.transparent=true;plane.material.opacity=.4;this.colliderGuides={sphere,box,plane};for(const guide of Object.values(this.colliderGuides))this.scene.add(guide);}
 for(const guide of Object.values(this.colliderGuides))guide.visible=false;if(!show||!s.bounce||s.motion==='orbit')return;const type=s.colliderType||'plane',guide=this.colliderGuides[type];if(!guide)return;guide.visible=true;if(type==='plane')guide.position.set(0,0,s.collisionHeight||0);else{guide.position.set(s.colliderX??0,s.colliderY??0,s.colliderZ??100);if(type==='sphere')guide.scale.setScalar(s.colliderRadius??50);else guide.scale.set(s.colliderSizeX??100,s.colliderSizeY??100,s.colliderSizeZ??100);}
};
